package de.buerokratiecopilot.runtime;

import org.springframework.boot.context.properties.ConfigurationProperties;

/**
 * Settings of the API-only runtime installation.
 *
 * <p>The admin token is generated by the installer and stored in the installation's
 * {@code runtime.env} (mode 600). It is not a user password and not an API token: it is the
 * operator's key for bootstrap and token administration, and it is the only credential that
 * exists before the first tenant does.</p>
 */
@ConfigurationProperties(prefix = "burokratie.runtime")
public class RuntimeProperties {

    /** Whether the runtime admin endpoints exist at all. The {@code runtime} profile sets it. */
    private boolean enabled = false;

    /** The per-installation operator secret; empty disables the admin endpoints. */
    private String adminToken = "";

    public boolean isEnabled() {
        return enabled;
    }

    public void setEnabled(boolean enabled) {
        this.enabled = enabled;
    }

    public String getAdminToken() {
        return adminToken;
    }

    public void setAdminToken(String adminToken) {
        this.adminToken = adminToken;
    }
}
